// Valida payload UAZAPI e extrai dados da msg do Thiago
// Numero do Thiago hardcoded (so ele fala com a Giulia por enquanto)
const THIAGO_NUMERO = '5511964486564';

const body = items[0].json.body || items[0].json;
const msg = body.message || body.data || body;

// Ignorar mensagens enviadas POR Giulia (fromMe)
const fromMe = msg.fromMe === true || msg.key?.fromMe === true;
if (fromMe) return [];

// Ignorar grupos
const chatId = String(msg.chatid || msg.chatId || msg.key?.remoteJid || '');
if (chatId.includes('@g.us') || chatId.includes('-')) return [];

// Extrair numero do remetente
const senderNumero = chatId.replace(/@.*$/, '').replace(/[^0-9]/g, '');

// Por enquanto so o Thiago pode usar a Giulia
if (senderNumero !== THIAGO_NUMERO) {
  return [];
}

// Extrair texto - varios formatos UAZAPI possiveis
const texto = msg.text
  || msg.body
  || msg.message?.conversation
  || msg.message?.extendedTextMessage?.text
  || msg.content
  || '';

if (!texto || !String(texto).trim()) return [];

// Timestamp atual em Brasilia (UTC-3) - server roda UTC-4
const agora = new Date(Date.now() + (1 * 60 * 60 * 1000)); // +1h pra Brasilia
const agoraISO = agora.toISOString().replace('T', ' ').substring(0, 19);

return [{
  json: {
    valido: true,
    sender_numero: senderNumero,
    texto: String(texto).trim(),
    timestamp_agora_brasilia: agoraISO,
    message_id: msg.id || msg.messageid || msg.key?.id || ''
  }
}];

// Junta msg atual + memoria + contatos e monta o prompt pra Gemini
const msgAtual = $('Validar Mensagem').first().json;
const memoria = $('Carregar Memoria 24h').all().map(i => i.json);
const contatos = $('Carregar Contatos').all().map(i => i.json);

// Formatar contatos pra prompt
const contatosTxt = contatos.map(c => {
  const apelidos = Array.isArray(c.apelidos) ? c.apelidos.join(', ') : (c.apelidos || '');
  return `- ${c.nome} (apelidos: ${apelidos}) numero=${c.numero}${c.observacoes ? ' obs: '+c.observacoes : ''}`;
}).join('\n');

// Formatar memoria (mais antiga primeiro)
const memOrdenada = memoria.slice().reverse();
const memTxt = memOrdenada.map(m => `[${m.role}] ${m.content}`).join('\n') || '(sem historico recente)';

const systemPrompt = `Voce e a Giulia, secretaria pessoal do Thiago Nicezio (dono ENG Solucoes).
Fala PT-BR direto, sem rodeio, sem hifens em listas, sem emojis a menos que ele use.

Voce recebe uma mensagem do Thiago e decide UMA acao a tomar.

ACOES disponiveis:
1. salvar_ideia - guardar uma ideia/anotacao que ele teve
2. criar_lembrete - voce mesma vai lembrar ele em data/hora especifica
3. agendar_mensagem - mandar mensagem pra OUTRA pessoa em data/hora futura
4. enviar_agora - mandar mensagem pra OUTRA pessoa agora
5. listar_ideias - mostrar ideias que ele salvou (com filtro opcional por tag)
6. listar_lembretes - mostrar lembretes pendentes
7. apenas_responder - so conversar, sem acao no banco

CONTATOS conhecidos (use o numero exato ao mandar mensagem):
${contatosTxt}

HISTORICO RECENTE (24h):
${memTxt}

MENSAGEM ATUAL DO THIAGO: "${msgAtual.texto}"
TIMESTAMP ATUAL (Brasilia): ${msgAtual.timestamp_agora_brasilia}

Responda SOMENTE JSON valido sem markdown, no formato:
{
  "acao": "salvar_ideia"|"criar_lembrete"|"agendar_mensagem"|"enviar_agora"|"listar_ideias"|"listar_lembretes"|"apenas_responder",
  "parametros": {
    "conteudo": "texto da ideia",
    "tags": ["tag1","tag2"],
    "descricao": "o que lembrar",
    "disparar_em": "YYYY-MM-DD HH:MM:SS",
    "recorrencia": null,
    "destinatario_numero": "55...",
    "destinatario_nome": "nome",
    "texto": "mensagem pra mandar",
    "filtro_tag": "opcional"
  },
  "resposta_pro_thiago": "texto curto confirmando o que voce fez ou perguntando o que falta"
}

Regras:
- Se ele falar "daqui a X horas/minutos", calcula a partir do timestamp atual.
- Se ele falar "amanha as 9h", interpreta como amanha 09:00:00 Brasilia.
- Se nao identificar o destinatario nos contatos, use apenas_responder e peca o numero.
- Para listas vazias de parametros, use null ou string vazia, mas mantenha as chaves.
- Datas SEMPRE em horario Brasilia.
- Se a mensagem nao se encaixa em nenhuma acao concreta, use apenas_responder.`;

return [{
  json: {
    sender_numero: msgAtual.sender_numero,
    texto_original: msgAtual.texto,
    timestamp_brasilia: msgAtual.timestamp_agora_brasilia,
    gemini_body: {
      contents: [{ parts: [{ text: msgAtual.texto }] }],
      systemInstruction: { parts: [{ text: systemPrompt }] },
      generationConfig: { temperature: 0.3, maxOutputTokens: 1500, responseMimeType: 'application/json' }
    }
  }
}];

// Parseia resposta Gemini, decide acao, monta SQL/HTTP params
const prev = $('Montar Prompt').first().json;
const geminiResp = items[0].json;

let rawText = '';
try {
  rawText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || '';
} catch(e) { rawText = ''; }

// Parse JSON defensivo
function parseJson(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
  const i = t.indexOf('{'); const j = t.lastIndexOf('}');
  if (i >= 0 && j > i) t = t.substring(i, j+1);
  try { return JSON.parse(t); } catch(e) { return null; }
}

const decisao = parseJson(rawText) || {
  acao: 'apenas_responder',
  parametros: {},
  resposta_pro_thiago: 'Desculpa, tive um problema processando aqui. Pode repetir?'
};

const acao = decisao.acao || 'apenas_responder';
const p = decisao.parametros || {};
const esc = s => String(s || '').replace(/'/g, "''");

// Monta SQL OR HTTP params dependendo da acao
let acao_tipo = 'REPLY_ONLY';
let sql_query = '';
let send_to_number = '';
let send_text = '';

if (acao === 'salvar_ideia') {
  acao_tipo = 'DB_OP';
  const tagsArr = Array.isArray(p.tags) ? p.tags.filter(Boolean) : [];
  const tagsSql = tagsArr.length ? `ARRAY[${tagsArr.map(t=>`'${esc(t)}'`).join(',')}]::TEXT[]` : 'NULL';
  sql_query = `INSERT INTO giulia_ideias (conteudo, tags) VALUES ('${esc(p.conteudo)}', ${tagsSql}) RETURNING id, conteudo;`;
} else if (acao === 'criar_lembrete') {
  acao_tipo = 'DB_OP';
  const rec = p.recorrencia ? `'${esc(p.recorrencia)}'` : 'NULL';
  sql_query = `INSERT INTO giulia_lembretes (descricao, disparar_em, recorrencia) VALUES ('${esc(p.descricao)}', '${esc(p.disparar_em)}'::TIMESTAMP, ${rec}) RETURNING id, descricao, disparar_em;`;
} else if (acao === 'agendar_mensagem') {
  acao_tipo = 'DB_OP';
  sql_query = `INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para) VALUES ('${esc(p.destinatario_numero)}', '${esc(p.destinatario_nome)}', '${esc(p.texto)}', '${esc(p.disparar_em || p.agendado_para)}'::TIMESTAMP) RETURNING id, destinatario_nome, agendado_para;`;
} else if (acao === 'enviar_agora') {
  acao_tipo = 'SEND_NOW';
  send_to_number = String(p.destinatario_numero || '').replace(/[^0-9]/g,'');
  send_text = String(p.texto || '');
} else if (acao === 'listar_ideias') {
  acao_tipo = 'DB_OP';
  const tag = p.filtro_tag ? esc(p.filtro_tag) : null;
  sql_query = tag
    ? `SELECT id, conteudo, tags, created_at FROM giulia_ideias WHERE '${tag}' = ANY(tags) ORDER BY created_at DESC LIMIT 20;`
    : `SELECT id, conteudo, tags, created_at FROM giulia_ideias ORDER BY created_at DESC LIMIT 20;`;
} else if (acao === 'listar_lembretes') {
  acao_tipo = 'DB_OP';
  sql_query = `SELECT id, descricao, disparar_em, recorrencia, status FROM giulia_lembretes WHERE status = 'pendente' ORDER BY disparar_em ASC LIMIT 20;`;
}

return [{
  json: {
    sender_numero: prev.sender_numero,
    texto_original: prev.texto_original,
    acao,
    acao_tipo,
    sql_query,
    send_to_number,
    send_text,
    resposta_pro_thiago: decisao.resposta_pro_thiago || 'Feito.',
    gemini_raw: rawText.substring(0, 500)
  }
}];

// Converge as 3 branches num so output
// $input.all() pega tudo que chegar aqui
const all = $input.all();
return all;

// Formata resposta final pro Thiago baseado na acao executada
// Vem da Decidir Acao + resultado da branch (DB ou HTTP)
const dec = $('Decidir Acao').first().json;
const acao = dec.acao;
let textoResposta = dec.resposta_pro_thiago || 'Feito.';

// Pra listas, formatar a saida do Postgres
if (acao === 'listar_ideias') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.conteudo);
  if (!rows.length) {
    textoResposta = 'Nenhuma ideia salva ainda.';
  } else {
    const linhas = rows.map((r, i) => {
      const tags = Array.isArray(r.tags) && r.tags.length ? ` [${r.tags.join(', ')}]` : '';
      return `${i+1}. ${r.conteudo}${tags}`;
    });
    textoResposta = `Tuas ideias salvas:\n${linhas.join('\n')}`;
  }
}
if (acao === 'listar_lembretes') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.descricao);
  if (!rows.length) {
    textoResposta = 'Nenhum lembrete pendente.';
  } else {
    const linhas = rows.map((r, i) => {
      const dt = new Date(r.disparar_em);
      const dtFmt = dt.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'short', timeStyle: 'short' });
      const rec = r.recorrencia ? ` (${r.recorrencia})` : '';
      return `${i+1}. ${dtFmt} - ${r.descricao}${rec}`;
    });
    textoResposta = `Lembretes pendentes:\n${linhas.join('\n')}`;
  }
}
if (acao === 'enviar_agora') {
  const status = $input.first()?.json?.status || $input.first()?.json?.statusCode;
  if (status && String(status).match(/^[45]/)) {
    textoResposta = `Tive problema ao mandar: ${status}. Tenta de novo?`;
  }
}

return [{
  json: {
    sender_numero: dec.sender_numero,
    texto_original: dec.texto_original,
    resposta_final: textoResposta
  }
}];

